                break

    def mode(panel):
        counts = {}
        for row in panel:
            for x in row:
                counts[x] = counts.get(x, 0) + 1
        return max(counts, key=counts.get)

    # The output highlights cells where the two panels share a non-background
    # color, using the first panel's dominant color as the fill.
    bg_a, bg_b = mode(a), mode(b)
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    shared = next((x for x in common if x != bg_a and x != bg_b), None)
    if shared is None:
        shared = next((x for x in common if x != bg_a), bg_a)

    return [
        [3 if a[r][c] == shared and b[r][c] == shared else bg_a
         for c in range(len(a[0]))]
